class Solution {
public:
    int numSubmat(vector<vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        vector<int> h(n, 0);
        int ans = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                h[j] = mat[i][j] ? h[j] + 1 : 0;
            }
            vector<int> stk;
            vector<int> dp(n, 0);
            for (int j = 0; j < n; j++) {
                while (!stk.empty() && h[stk.back()] >= h[j]) {
                    stk.pop_back();
                }
                int prev = stk.empty() ? -1 : stk.back();
                dp[j] = (prev == -1 ? 0 : dp[prev]) + h[j] * (j - prev);
                ans += dp[j];
                stk.push_back(j);
            }
        }
        return ans;
    }
};
